'use strict';
const M=window.PauseModel;let state=M.create();const main=document.querySelector('#main'),dialog=document.querySelector('#controls');let noticeTimer;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function send(type,value,extra={}){state=M.transition(state,{type,value,...extra});render();}
function notice(text){const n=document.querySelector('#notice');n.textContent=text;n.hidden=false;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>n.hidden=true,4500);}
function row(id,title,description,index,action='select'){return `<button class="choice" data-action="${action}" data-value="${id}"><span class="choice-num">${String(index).padStart(2,'0')}</span><span><span class="choice-title">${title}</span>${description?`<span class="choice-description">${description}</span>`:''}</span><span class="choice-symbol" aria-hidden="true">+</span></button>`;}
function left(label,title,description,note='',back=''){return `<section class="left-copy">${back?`<button class="text-button back-button" data-action="back" data-value="${back}">Back to ${back==='options'?'the options':'the question'}</button>`:''}<span class="overline">${label}</span><h1>${title}</h1><p class="lede">${description}</p>${note?`<p class="margin-note">${note}</p>`:''}</section>`;}
function render(focus=true){
 document.querySelectorAll('[data-entry]').forEach(b=>{const active=b.dataset.entry===(state.view==='checkin'?'scrolling':'needs');if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});
 if(state.view==='needs')main.innerHTML=`<div class="spread">${left('01 / BEFORE THE NEXT APP','What did you want<br>from <em>this break?</em>','Sometimes you want a rest. Sometimes you just want something other than the assignment.','You can skip this question.<br>There’s no answer you’re supposed to pick.')}<section aria-label="Choose what you need"><div class="choice-heading"><span>I WAS LOOKING FOR…</span><span>Pick what feels closest.</span></div>${M.needs.map((n,i)=>row(n.id,n.title,n.description,i+1,'need')).join('')}<div class="under-options"><button class="text-button" data-action="skip">Skip. Show me a few ideas.</button><button class="text-button" data-action="select" data-value="scroll">I just want to scroll.</button></div></section></div>`;
 if(state.view==='options'){const need=M.needs.find(x=>x.id===state.need);main.innerHTML=`<div class="spread">${left('02 / A BREAK THAT FITS','What might<br><em>give you that?</em>',`You said: “${esc(need?.title||'I’m not sure')}.”`,'These are suggestions, not tasks.<br>You don’t need to complete anything.','needs')}<section aria-label="Break options"><div class="choice-heading"><span>A FEW POSSIBILITIES</span><span>Or do your own thing.</span></div>${M.getOptions(state).map((o,i)=>row(o.id,o.title,o.description,i+1)).join('')}<div class="under-options"><button class="text-button" data-action="select" data-value="nothing-fallback">I’d rather do nothing.</button></div></section></div>`;}
 if(state.view==='plan'){const o=state.selected;main.innerHTML=`<div class="spread">${left('03 / YOUR CHOICE',o.id==='scroll'?'A scroll.<br><em>By choice.</em>':'Make it<br><em>your break.</em>',o.id==='scroll'?'You don’t need to replace it with something “better”. Decide what you want from it.':'One small decision, then you can leave this page.',o.id==='scroll'?'This page cannot detect videos, app use, or when you reach a stopping point.':'There’s no timer unless you ask for one.','options')}<section><form id="break-form"><div class="plan-sheet"><span class="sheet-label">I’M GOING TO</span><h3>${esc(o.title)}</h3><p>${esc(o.instruction)}</p>${o.id==='own'?'<label class="field-label" for="custom-break">What would you like to do?</label><input id="custom-break" type="text" maxlength="160" required placeholder="Call my sister, sit outside…">':''}<label class="field-label" for="stopping-cue">A moment to decide what’s next <span>Optional</span></label><input id="stopping-cue" type="text" maxlength="160" value="${esc(state.cue)}" placeholder="Leave this empty to keep it open-ended"><div class="field-help">This is a note for you. Nothing stops automatically.</div></div><details class="optional-reminder"><summary>I’d like a timed check-in, too</summary><p>One quiet message on this page. No alarm, lockout, or automatic return to study. You’ll see it when this tab is open.</p><label class="field-label" for="reminder">Check in after</label><select id="reminder"><option value="0">No timed check-in</option><option value="5">About 5 minutes</option><option value="10">About 10 minutes</option><option value="15">About 15 minutes</option></select></details><button class="primary wide" type="submit">${o.id==='scroll'?'I’ll go with that':'Take this break'}</button></form></section></div>`;}
 if(state.view==='away'){const o=state.selected;main.innerHTML=`<div class="spread">${left('OFF FOR A BIT','You can leave<br><em>this screen.</em>',o.id==='scroll'?'Open the app you had in mind. You can come back here if the break stops feeling like the one you wanted.':'Go do what you chose. You can come back here when you want to decide what’s next.','You can use your device normally.<br>This page won’t follow you.')}<section><div class="receipt"><div class="receipt-top"><span>MY BREAK</span><span>NO TASK TO COMPLETE</span></div><div class="receipt-body"><h3>${esc(state.custom||o.title)}</h3><p>${esc(o.instruction)}</p>${state.cue?`<div class="cue-note"><span>A MOMENT TO DECIDE</span><p>${esc(state.cue)}</p></div>`:'<p class="no-timer">I’m leaving this one open-ended.</p>'}</div><div class="receipt-foot">${state.deadline?'You asked for a check-in in about '+state.reminder+' minutes. It will appear here.':'No timer or reminders running.'}</div></div><div class="action-row"><button class="primary" data-action="checkin">${o.id==='scroll'?'I want to check in':'I’m back'}</button></div><div class="quiet-links"><button class="text-button" data-action="rethink">Choose something else</button><button class="text-button" data-action="off">Turn support off</button>${state.deadline?'<button class="text-button" data-action="cancel-reminder">Cancel check-in</button>':''}</div>${state.deadline?'<button class="demo-link" data-action="demo">PROTOTYPE: SHOW THE CHECK-IN NOW</button>':''}</section></div>`;}
 if(state.view==='checkin')main.innerHTML=`<div class="spread">${left(state.source==='timed'?'THE CHECK-IN YOU ASKED FOR':'A MOMENT TO NOTICE','Still the break<br><em>you wanted?</em>',state.source==='timed'?'The time you chose has passed. That doesn’t mean your break needs to end.':state.selected?.id==='scroll'?'Maybe you’ve been scrolling longer than you meant to. Maybe this is exactly what you needed.':'You took a break. You can decide whether you want more of it, something different, or to move on.','You decide what happens next.<br>Returning to study is one option.')}<section><div class="feedback"><p>Did this give you what you needed? <span class="small-note">Optional</span></p><div class="feedback-options" role="group" aria-label="How this break felt">${[['yes','Yes, it did'],['unsure','I’m not sure'],['no','Not really']].map(([v,t])=>`<button data-action="feedback" data-value="${v}" aria-pressed="${state.feedback===v}">${t}</button>`).join('')}</div></div><div class="choice-heading"><span>WHAT I WANT NOW</span><span>No right answer.</span></div>${row('continue',state.selected?.id==='scroll'?'Keep scrolling, by choice':'Keep taking this break','No further reminders for this break.',1,'next-choice')}${row('rethink','Try a different kind of break','Find something closer to what I need.',2,'next-choice')}${row('plan','Change my study plan','Reconsider what I want to do next.',3,'next-choice')}${row('return','Go back to studying','If that’s what feels right now.',4,'next-choice')}${row('end','Finish studying for now','Leave it here for today.',5,'next-choice')}<div class="under-options"><button class="text-button" data-action="continue">Skip this. Keep my break open.</button></div></section></div>`;
 if(state.view==='new-plan')main.innerHTML=`<div class="spread">${left('A DIFFERENT NEXT STEP','The plan<br><em>can change.</em>','You might choose a smaller task, something more urgent, or no more studying today.','This note stays in this tab.<br>It isn’t a commitment or a checklist.')}<section><form id="next-form"><div class="choice-heading"><span>WHAT I WANT TO DO NEXT</span><span>Optional.</span></div><label class="field-label" for="next-note">A note to myself</label><textarea id="next-note" rows="5" maxlength="500" placeholder="Have lunch first. Then decide whether to tackle the reading.">${esc(state.nextNote)}</textarea><div class="action-row"><button class="primary" type="submit">Go with this</button><button class="secondary" type="button" data-action="save-empty">Continue without a note</button></div></form></section></div>`;
 if(state.view==='done'){const copy={return:['Back to it,<br><em>when you’re ready.</em>','You’ve chosen to return to studying. Close this page whenever you want.'],end:['Leave it<br><em>here for today.</em>','You’ve chosen to finish studying. There’s nothing else to fill in.'],plan:['A different<br><em>next step.</em>','You’ve changed your plan. You can close this page and go with what you decided.']};const [h,p]=copy[state.outcome];main.innerHTML=`<div class="spread">${left('YOUR DECISION',h,p)}<section>${state.nextNote&&state.outcome==='plan'?`<div class="choice-heading"><span>MY NEXT STEP</span></div><p class="result-note">${esc(state.nextNote)}</p>`:'<p class="small-note">Your choices aren’t added to a log or a score. They disappear when you reload this tab.</p>'}<div class="action-row"><button class="secondary" data-action="reset">Start a new break</button></div></section></div>`;}
 if(state.view==='off')main.innerHTML=`<section class="off-view"><span class="overline">SUPPORT IS OFF</span><h1>Nothing else<br><em>from us.</em></h1><p class="lede">No check-ins are running. Keep resting, keep scrolling, or close this page.</p><button class="primary" data-action="reset">Use Pause again</button></section>`;
 document.querySelector('#cancel-reminder').disabled=state.deadline===null;
 if(focus){main.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}
}
main.addEventListener('click',e=>{const b=e.target.closest('button[data-action]');if(!b)return;const a=b.dataset.action,v=b.dataset.value;switch(a){case'need':send('NEED',v);break;case'skip':send('SKIP');break;case'select':if(v==='nothing-fallback'){state=M.transition(state,{type:'NEED',value:'switch-off'});send('SELECT','nothing');}else send('SELECT',v);break;case'back':send('BACK',v);break;case'checkin':send('CHECKIN');break;case'feedback':state=M.transition(state,{type:'FEEDBACK',value:v});main.querySelectorAll('[data-action=feedback]').forEach(x=>x.setAttribute('aria-pressed',x.dataset.value===v));break;case'continue':send('CONTINUE');break;case'rethink':send('RETHINK');break;case'next-choice':if(v==='continue')send('CONTINUE');else if(v==='rethink')send('RETHINK');else send('NEXT',v);break;case'cancel-reminder':send('CANCEL_REMINDER');notice('Check-in cancelled. Nothing else will appear.');break;case'off':send('OFF');break;case'reset':send('RESET');break;case'save-empty':send('SAVE_PLAN','');break;case'demo':state=M.transition(state,{type:'TICK'},state.deadline);render();break;}});
main.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='break-form'){send('START',undefined,{cue:document.querySelector('#stopping-cue').value,custom:document.querySelector('#custom-break')?.value||'',minutes:Number(document.querySelector('#reminder').value)});}else if(e.target.id==='next-form')send('SAVE_PLAN',document.querySelector('#next-note').value);});
document.querySelectorAll('[data-entry]').forEach(b=>b.addEventListener('click',()=>send('ENTRY',b.dataset.entry)));
function openControls(){document.querySelector('#cancel-reminder').disabled=state.deadline===null;dialog.showModal();}
document.querySelector('#controls-open').addEventListener('click',openControls);document.querySelector('#privacy-open').addEventListener('click',openControls);document.querySelector('#controls-close').addEventListener('click',()=>dialog.close());document.querySelector('#support-off').addEventListener('click',()=>{dialog.close();send('OFF');});document.querySelector('#cancel-reminder').addEventListener('click',()=>{send('CANCEL_REMINDER');dialog.close();notice('Timed check-in cancelled.');});
function tick(){const next=M.transition(state,{type:'TICK'});if(next.view!==state.view){state=next;render();}}
setInterval(tick,1000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)tick();});render(false);
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'get_break_state',description:'Read the current screen, selected need, break choice, and whether a check-in is scheduled. Does not start, complete, or change a break.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({screen:state.view,need:state.need,breakChoice:state.selected?.id||null,timedCheckIn:state.deadline!==null,supportEnabled:state.enabled})})).catch(()=>{});}catch{}}
